  "We also text them the link. Good for supervisors who don’t check email. The number is deleted after 30 days.": "リンクは SMS でも送ります。メールを見ない監督者に便利です。番号は30日後に削除されます。",
  "{organizer} reviews and signs this on their My Tasks page in VolunTrack — no email is sent.": "{organizer}が VolunTrack の「マイタスク」ページで確認してサインします。メールは送信されません。",
  "The task organizer": "タスクの主催者",
  "Your supervisor will get an email with a link to review these hours. If they approve, they'll sign right there to confirm it — if they reject, no signature is needed. This usually takes a day or two.": "監督者には時間を確認するためのリンク付きメールが届きます。承認する場合はそこでサインし、却下する場合はサイン不要です。通常1〜2日かかります。",
  "Supervisor signature": "監督者のサイン",
