  "Other language…": "その他の言語…",
  "Open VolunTrack in your phone’s web browser (Chrome or Safari) using the button below, and sign in.": "下のボタンでスマホのブラウザ（Chrome または Safari）で VolunTrack を開き、ログインしてください。",
  "Then use the browser’s translate, as shown below.": "次に、下のようにブラウザの翻訳機能を使ってください。",
  "Use VolunTrack in another language": "VolunTrack を他の言語で使う",
  "VolunTrack is written in English, Spanish, Vietnamese and Chinese, and its main screens in Hindi, Arabic, Portuguese, French, Bengali, Russian and Japanese. For any other language, your browser can translate the page for you. It’s free and works for 100+ languages, like Tagalog, Korean, Haitian Creole, German and Urdu.": "VolunTrack は英語、スペイン語、ベトナム語、中国語に対応し、主な画面はヒンディー語、アラビア語、ポルトガル語、フランス語、ベンガル語、ロシア語、日本語にも対応しています。その他の言語は、ブラウザでページを翻訳できます。無料で、タガログ語、韓国語、ハイチ・クレオール語、ドイツ語、ウルドゥー語など100以上の言語に対応しています。",
  "computer": "パソコン",
