  "Tap ⋮ (top right), then Translate…, then pick your language.": "⋮（右上）をタップし、「翻訳…」を選んで言語を選択してください。",
  "iPhone": "iPhone",
  "Tap the page menu (aA or the icon at the left of the address bar), then Translate to….": "ページメニュー（aA またはアドレスバー左のアイコン）をタップし、「翻訳」を選んでください。",
  "Mac": "Mac",
  "Click the translate icon in the address bar, or choose View → Translation.": "アドレスバーの翻訳アイコンをクリックするか、「表示 → 翻訳」を選んでください。",
  "Browser translation is done by your browser, not by VolunTrack, and may not be perfect. Emails still come in English or your chosen VolunTrack language.": "ブラウザの翻訳は VolunTrack ではなくブラウザが行うため、完璧ではない場合があります。メールは引き続き英語、または VolunTrack で選んだ言語で届きます。",
  "Open in browser": "ブラウザで開く",
  "Got it": "わかりました",
  "Default": "標準",
  "Large": "大",
