  "Accessibility": "アクセシビリティ",
  "Make VolunTrack easier to read. These settings are saved on this device only.": "VolunTrack を読みやすくします。これらの設定はこの端末にのみ保存されます。",
  "Brighter text, stronger borders and focus outlines, and underlined links.": "明るい文字、はっきりした枠線とフォーカス表示、下線付きのリンク。",
  "A font that keeps similar letters like I, l and 1 easy to tell apart. Can help with dyslexia or low vision.": "I、l、1 など似た文字を区別しやすいフォントです。ディスレクシアや弱視の方に役立つことがあります。",
  "The short version": "要約",
  "The full": "正式な内容は全文の",
  "are what count.": "に従います。",
  "Set a goal and your dashboard will show how close you are. You can change it any time in Settings.": "目標を設定すると、ダッシュボードで進み具合を確認できます。いつでも設定で変更できます。",
  "Goal name": "目標の名前",
