  "A password recovery code has been emailed to": "パスワード再設定コードをメールで送りました：",
  ". It expires in 15 minutes.": "。有効期限は15分です。",
  "Look for an email from": "次の差出人からのメールを探してください：",
  "Don't see it? Check the Spam folder and Promotions/Updates tab.": "見つからない場合は、迷惑メールフォルダやプロモーション/新着タブを確認してください。",
  "This deployment is a static site, so there’s no email server reachable from here. The password recovery code is shown below — only you can see this screen.": "この環境は静的サイトのため、メールサーバーに接続できません。再設定コードは下に表示されます。この画面はあなただけが見られます。",
  "Email delivery is not available right now": "現在メールを送信できません",
  ". Use the code below to continue.": "。下のコードを使って続けてください。",
  "Add": "追加：",
  "to your": "の",
