  "Registration failed": "登録に失敗しました",
  "Finish setting up your school": "学校の設定を完了",
  "Start a free club": "無料クラブを始める",
  "Register your school": "学校を登録",
  "You were invited to VolunTrack. Just set your password and school code.": "VolunTrack に招待されました。パスワードと学校コードを設定するだけです。",
  "Free for one club or class, up to 50 students, with every school feature. No code needed.": "1つのクラブまたはクラス、最大50人の生徒まで無料。学校のすべての機能が使えます。コードは不要です。",
  "Create a school account to review student hours, using the registration code we sent you.": "お送りした登録コードを使って学校アカウントを作成し、生徒の時間を確認しましょう。",
  "Plan": "プラン",
  "Up to 50 students": "生徒50人まで",
