  "Registering…": "登録中…",
  "Start free club": "無料クラブを始める",
  "Wrong email or no code? Go back": "メールアドレスが違う・コードが届かない場合は戻る",
  "Club or school name": "クラブ名または学校名",
  "School name": "学校名",
