  "Turned off for VolunTrack in your phone’s settings. Turn them on there to get reminders when the app is closed.": "スマホの設定で VolunTrack の通知がオフになっています。アプリを閉じているときにリマインダーを受け取るには、そちらでオンにしてください。",
