  "Subscribe once and the tasks you signed up for or posted show up in your phone or computer calendar, and stay up to date.": "一度登録すると、申し込んだタスクや投稿したタスクがスマホやパソコンのカレンダーに表示され、自動で最新に保たれます。",
  "Get my calendar link": "カレンダーのリンクを取得",
