  "Privacy": "プライバシー",
  "Your logged hours are stored on this device. If you've created an account, some features above (Family sharing, school linking, cross-device sync, two-factor authentication) also store data on our server. Sign out below to clear your session.": "記録した時間はこの端末に保存されます。アカウントを作成している場合、上の一部の機能（家族との共有、学校との連携、端末間の同期、2段階認証）はサーバーにもデータを保存します。下からログアウトするとセッションが消去されます。",
