  "Confirm account deletion": "アカウント削除の確認",
  "This is permanent. Your volunteer logs, goals, achievements, and reminder data will be erased.": "この操作は取り消せません。ボランティアの記録、目標、実績、リマインダーのデータが消去されます。",
  "Type {word} to confirm.": "確認のため{word}と入力してください。",
  "Type delete to confirm": "確認のため delete と入力してください",
