  "Notices for every school you own": "所有するすべての学校へのお知らせ",
  "Nonprofits shared with every school you own": "所有するすべての学校と共有する非営利団体",
  "Export hours across your schools": "学校全体の時間をエクスポート",
  "Schools": "学校",
