  "The new principal gets an email to accept and becomes the main admin of {school}. The current one stays as a co-admin and is signed out.": "新しい校長に承認用のメールが届き、{school}のメイン管理者になります。現在の管理者は共同管理者として残り、ログアウトされます。",
  "Loading invites…": "招待を読み込み中…",
  "No invites sent": "送信した招待はありません",
  "Add a school and they'll get a link to finish setup themselves.": "学校を追加すると、その学校に設定を完了するためのリンクが届きます。",
  "Set up": "設定済み",
  "Expired": "期限切れ",
  "Someone new running the organization?": "団体の運営者が変わりましたか？",
  "Hand this organization’s account to them. They get an email to accept and set their own password. When they do, this login is removed from the organization and signed out.": "この団体のアカウントを新しい人に引き継ぎます。相手には承認と自分のパスワード設定のためのメールが届きます。承認されると、このログインは団体から外され、ログアウトされます。",
  "They'll get an email with a link to set their own password and school code. The link expires in 3 days.": "自分のパスワードと学校コードを設定するためのリンク付きメールが届きます。リンクの有効期限は3日です。",
  "Send invite": "招待を送信",
  "Connection saved. Run a test to verify it before enabling.": "接続を保存しました。有効にする前にテストして確認してください。",
