  "The organizer of an event {name} signed up for sees this on their check-in list, only around the day of the event. It isn’t shown anywhere else.": "{name}さんが申し込んだイベントの主催者は、イベント当日の前後だけ、チェックインの一覧でこれを見られます。ほかの場所には表示されません。",
