  "K–5th grade: parent comes too": "幼稚園〜5年生：保護者も同伴",
  "They’ll tell you which parent or guardian is coming when they sign up.": "申し込むときに、どの保護者が来るかを教えてくれます。",
  "1 entry is saved on this device and waiting to send.": "1件の記録がこの端末に保存され、送信を待っています。",
