  "Couldn’t reach VolunTrack yet. It keeps trying by itself.": "まだ VolunTrack に接続できません。自動で試し続けます。",
  "They send by themselves when you’re back online.": "オンラインに戻ると自動で送信されます。",
  "Send now": "今すぐ送信",
  "Saved on this device. It sends by itself when you’re back online.": "この端末に保存しました。オンラインに戻ると自動で送信されます。",
  "Waiting to send": "送信待ち",
  "Could not make the packet.": "パケットを作成できませんでした。",
  "End-of-year packet": "年度末パケット",
  "One ZIP with a folder for each school: summary, every entry, and each student’s hours report.": "学校ごとのフォルダが入った1つの ZIP：概要、すべての記録、各生徒の時間レポート。",
  "One ZIP with the summary, every entry, the approval history, certificates for students who met the requirement, and each student’s hours report.": "概要、すべての記録、承認履歴、必要時間を達成した生徒の証明書、各生徒の時間レポートが入った1つの ZIP。",
  "School year": "年度",
