  "Download packet": "パケットをダウンロード",
  "School year runs August 1 to July 31. The ZIP has students’ personal information, so keep it somewhere safe.": "年度は8月1日から7月31日までです。ZIP には生徒の個人情報が含まれるので、安全な場所に保管してください。",
