  "Tick the times that work for you. \"When I'm free\" then shows only events that start then. Only you see this.": "都合のいい時間にチェックを入れてください。「空いている時間」で、その時間に始まるイベントだけが表示されます。これはあなただけが見られます。",
  "Morning is before noon, afternoon noon to 5 PM, evening after 5 PM.": "午前は正午まで、午後は正午〜午後5時、夕方以降は午後5時以降です。",
