  "Copy this link to them:": "このリンクを相手にコピーして送ってください：",
  "{n} entries waiting. Works for {days} days; a new link replaces this one.": "{n}件の記録が待っています。{days}日間有効です。新しいリンクを作るとこのリンクは置き換わります。",
  "Sign-off link": "確認用リンク",
  "Confirmed by a parent: {name}": "保護者が確認済み：{name}",
