  "You stayed {stayed} of the {minimum} minutes this event asks for, so the organizer will review your hours.": "このイベントが求める{minimum}分のうち{stayed}分の滞在だったため、主催者が時間を確認します。",
  "1 hour sent to the organizer to sign.": "1時間を主催者のサイン待ちに送りました。",
