  "Only their clubs": "担当クラブのみ",
  "They see only students in the clubs they advise: student list, hours to check, progress and reports.": "担当しているクラブの生徒だけが表示されます：生徒一覧、確認が必要な時間、進み具合、レポート。",
  "Assignments": "課題",
