  "no reflection yet": "まだふりかえりがありません",
  "Write a reflection (\"What did you learn?\") on one of the entries you add.": "追加する記録の1つについて、ふりかえり（「何を学びましたか？」）を書いてください。",
  "Remove this entry": "この記録を外す",
  "Add an entry to {title}": "{title}に記録を追加",
  "+ Add one of your entries…": "+ 自分の記録を追加…",
  "New club assignment": "新しいクラブの課題",
  "Event check-in and check-out: we keep your check-in and check-out times, and kiosk and check-out PINs are stored scrambled.": "イベントのチェックインとチェックアウト：チェックイン・チェックアウトの時刻を保存し、キオスクとチェックアウトの PIN は暗号化して保存します。",
  "If you tick when you are usually free, only you see it.": "ふだん空いている時間にチェックを入れた場合、それを見られるのはあなただけです。",
  "Parents can confirm a young child's hours (kindergarten to 5th grade); schools see who confirmed.": "保護者は小さな子ども（幼稚園〜5年生）の時間を確認でき、学校には誰が確認したかが表示されます。",
  "Clubs and assignments: advisers see your hours and only whether you wrote a reflection, never what it says.": "クラブと課題：アドバイザーにはあなたの時間と、ふりかえりを書いたかどうかだけが表示され、内容は表示されません。",
  "Partner sign-off: a district's partner nonprofit can confirm hours logged with them and sees only your first name, last initial, school, activity, date and hours.": "提携先による確認：学区の提携非営利団体は、そこで記録された時間を確認でき、見られるのはあなたの名、姓のイニシャル、学校、活動、日付、時間だけです。",
  "Don't check in or out for someone else or share a PIN; parents and partners confirm only what they know happened.": "ほかの人の代わりにチェックイン・チェックアウトしたり、PIN を共有したりしないでください。保護者と提携先は、実際にあったと知っていることだけを確認します。",
  "The short version:": "要点：",
